<script setup lang="ts">
import {computed,onMounted,ref} from "vue";
import {ElMessage} from "element-plus";
import {useI18n} from "vue-i18n";
import {BusinessWorkspace} from "@appnexus/ui";
import type {AuthorizationCenterApi,DataPolicy,DataScopeType,PermissionItem,RoleItem,RoleManagementApi,ScopeSupport,AuthorizationOption} from "./index";
const props=defineProps<{roleApi:RoleManagementApi;api:AuthorizationCenterApi;errorText:(error:unknown)=>string}>();
const {t,locale}=useI18n();const roles=ref<RoleItem[]>([]),permissions=ref<PermissionItem[]>([]),metadata=ref<ScopeSupport[]>([]),organizations=ref<AuthorizationOption[]>([]);const roleId=ref(""),selected=ref<string[]>([]),policies=ref<Record<string,DataPolicy>>({}),version=ref(0),reason=ref(""),loading=ref(false),saving=ref(false),error=ref("");
const selectedRole=computed(()=>roles.value.find(item=>item.id===roleId.value));const grouped=computed(()=>Object.entries(permissions.value.reduce<Record<string,PermissionItem[]>>((all,item)=>{(all[item.resource]??=[]).push(item);return all;},{})));
function supports(id:string){return metadata.value.filter(item=>item.permissionId===id)}function label(item:PermissionItem){return locale.value.startsWith("zh")?item.nameZh:item.nameEn}function needsOrganizations(type?:DataScopeType){return type==="ORGANIZATION"||type==="ORGANIZATION_SUBTREE"}
function toggle(id:string,enabled:boolean){if(enabled){if(!selected.value.includes(id))selected.value.push(id);}else{selected.value=selected.value.filter(value=>value!==id);delete policies.value[id];}}
function scopeChanged(permissionId:string,type:DataScopeType){const support=supports(permissionId).find(item=>item.scopeType===type);if(!support)return;policies.value[permissionId]={permissionId,scopeType:type,resourceType:support.resourceType,organizationIds:[]};}
async function loadAssignment(){if(!roleId.value)return;loading.value=true;error.value="";try{const value=await props.api.assignment(roleId.value);selected.value=[...value.permissionIds];policies.value=Object.fromEntries(value.dataPolicies.map(item=>[item.permissionId,{...item,organizationIds:[...item.organizationIds]}]));version.value=value.roleVersion;reason.value="";}catch(cause){error.value=props.errorText(cause);}finally{loading.value=false;}}
async function load(){loading.value=true;error.value="";try{const [page,items,support,orgs]=await Promise.all([props.roleApi.list({query:"",status:"ENABLED",page:1,pageSize:100}),props.api.permissions(),props.api.metadata(),props.api.organizationOptions?.()??Promise.resolve([])]);roles.value=page.items;permissions.value=items;metadata.value=support;organizations.value=orgs;if(roles.value.length){roleId.value=roles.value[0].id;await loadAssignment();}}catch(cause){error.value=props.errorText(cause);}finally{loading.value=false;}}
const invalid=computed(()=>selected.value.some(id=>supports(id).length&&!policies.value[id])||Object.values(policies.value).some(item=>needsOrganizations(item.scopeType)&&!item.organizationIds.length)||!reason.value.trim());
async function save(){if(!roleId.value||invalid.value)return;saving.value=true;error.value="";try{const value=await props.api.replace(roleId.value,{ids:[...selected.value],dataPolicies:Object.values(policies.value),version:version.value,reason:reason.value.trim()});version.value=value.roleVersion;reason.value="";ElMessage.success(t("authorizationCenter.saved"));}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
onMounted(load);
</script>
<template><BusinessWorkspace :title="t('authorizationCenter.title')" :description="t('authorizationCenter.description')"><template #feedback><el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><el-button link type="primary" @click="load">{{t('account.retry')}}</el-button></el-alert></template><template #data><div v-loading="loading" class="authorization-grid"><section class="authorization-pane"><h2>{{t('authorizationCenter.roles')}}</h2><el-empty v-if="!roles.length" :description="t('authorizationCenter.noRoles')" /><el-menu v-else :default-active="roleId" @select="value=>{roleId=String(value);loadAssignment()}"><el-menu-item v-for="role in roles" :key="role.id" :index="role.id"><span>{{role.name}}</span><small>{{role.code}}</small></el-menu-item></el-menu></section><section class="authorization-pane permission-pane"><h2>{{t('authorizationCenter.permissions')}}</h2><el-empty v-if="!permissions.length" :description="t('authorizationCenter.noPermissions')" /><div v-for="[resource,items] in grouped" :key="resource" class="permission-group"><h3>{{resource}}</h3><div v-for="item in items" :key="item.id" class="permission-row"><el-checkbox :model-value="selected.includes(item.id)" @change="value=>toggle(item.id,Boolean(value))"><strong>{{label(item)}}</strong><span>{{item.code}}</span></el-checkbox><template v-if="selected.includes(item.id)&&supports(item.id).length"><el-select :model-value="policies[item.id]?.scopeType" :placeholder="t('authorizationCenter.selectScope')" @change="value=>scopeChanged(item.id,value as DataScopeType)"><el-option v-for="support in supports(item.id)" :key="support.scopeType" :label="t('authorizationCenter.scopes.'+support.scopeType)" :value="support.scopeType" /></el-select><el-select v-if="needsOrganizations(policies[item.id]?.scopeType)" v-model="policies[item.id].organizationIds" multiple filterable :placeholder="t('authorizationCenter.selectOrganizations')"><el-option v-for="organization in organizations" :key="organization.id" :label="organization.name" :value="organization.id" /></el-select></template></div></div></section><section class="authorization-pane summary-pane"><h2>{{t('authorizationCenter.summary')}}</h2><p>{{selectedRole?.name||'—'}}</p><el-statistic :title="t('authorizationCenter.selectedCount')" :value="selected.length" /><el-form label-position="top" @submit.prevent="save"><el-form-item :label="t('authorizationCenter.reason')" required><el-input v-model="reason" type="textarea" :maxlength="500" show-word-limit /></el-form-item><el-alert v-if="invalid&&selected.length" type="warning" :title="t('authorizationCenter.incomplete')" :closable="false" show-icon /><el-button class="save-button" type="primary" native-type="submit" :loading="saving" :disabled="invalid">{{t('organization.save')}}</el-button></el-form></section></div></template></BusinessWorkspace></template>
<style scoped>.authorization-grid{display:grid;grid-template-columns:minmax(220px,1fr) minmax(360px,2fr) minmax(260px,1fr);min-height:560px;border:1px solid var(--el-border-color);border-radius:var(--el-border-radius-base);overflow:hidden}.authorization-pane{padding:16px;background:var(--el-bg-color)}.authorization-pane+.authorization-pane{border-left:1px solid var(--el-border-color)}h2{font-size:16px;margin:0 0 16px}.el-menu{border-right:0}.el-menu-item{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;line-height:1.4}.el-menu-item small,.permission-row span{color:var(--el-text-color-secondary);font-size:12px}.permission-group{margin-bottom:20px}.permission-group h3{font-size:14px;color:var(--el-text-color-regular)}.permission-row{display:grid;grid-template-columns:minmax(240px,1fr) 180px minmax(180px,1fr);gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--el-border-color-lighter)}.permission-row :deep(.el-checkbox__label){display:flex;flex-direction:column}.save-button{width:100%}@media(max-width:900px){.authorization-grid{grid-template-columns:1fr}.authorization-pane+.authorization-pane{border-left:0;border-top:1px solid var(--el-border-color)}.permission-row{grid-template-columns:1fr}.authorization-pane{padding:12px}:deep(.el-button){min-height:44px}}</style>
